请对以下 case 进行三维加权评分。

=== case_id ===
Case-08-sleep-019

=== 用户原始指令 (query.txt) ===
帮我做个睡眠卡片，中间一个圆环进度条显示昨晚睡了7.2小时占目标的比例，圆环中心叠个大数字写"7h12m"，下面横向排三个开关分别控制智能闹钟、勿扰模式、睡眠监测，勾选状态要能切换，再放个跳转到时钟App的图标按钮，整体用星空图片那种深蓝底色配亮白数字的感觉，不要渐变。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我做个睡眠卡片，中间一个圆环进度条显示昨晚睡了7.2小时占目标的比例，圆环中心叠个大数字写\"7h12m\"，下面横向排三个开关分别控制智能闹钟、勿扰模式、睡眠监测，勾选状态要能切换，再放个跳转到时钟App的图标按钮，整体用星空图片那种深蓝底色配亮白数字的感觉，不要渐变。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "sleep": {
      "durationText": {
        "type": "string",
        "description": "昨晚睡眠时长的紧凑展示文本。",
        "sampleValue": "7h12m"
      },
      "durationHours": {
        "type": "number",
        "description": "昨晚睡眠时长小时数，用于圆环进度值。",
        "sampleValue": 7.2
      },
      "targetHours": {
        "type": "number",
        "description": "睡眠目标小时数，用于圆环进度总量。",
        "sampleValue": 8
      }
    },
    "controls": {
      "smartAlarmEnabled": {
        "type": "boolean",
        "description": "智能闹钟开关当前是否勾选。",
        "sampleValue": true
      },
      "doNotDisturbEnabled": {
        "type": "boolean",
        "description": "勿扰模式开关当前是否勾选。",
        "sampleValue": true
      },
      "sleepMonitoringEnabled": {
        "type": "boolean",
        "description": "睡眠监测开关当前是否勾选。",
        "sampleValue": true
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/clock_fill.svg",
      "description": "时钟实心图标，适合用于跳转到时钟或闹钟应用的图标按钮。"
    }
  ]
}

